import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

// Generated bytes stay outside source control. Frame IDs use eight visible binary cells.
const output = resolve(process.argv[2] ?? "data/media-playback-fixtures");
mkdirSync(output, { recursive: true });
const commands: string[][] = [];
function run(command: string, args: string[], input?: Buffer): Buffer {
	commands.push([command, ...args]);
	return execFileSync(command, args, { input, maxBuffer: 32 * 1024 * 1024 });
}
function encode(name: string, args: string[], input?: Buffer) {
	run(
		"ffmpeg",
		["-v", "error", "-y", ...args, "-threads", "1", "-fflags", "+bitexact", resolve(output, name)],
		input,
	);
}

for (const rate of [44100, 48000]) {
	const pcm = Buffer.alloc(rate * 2 * 4);
	for (let sample = 0; sample < rate * 2; sample++) {
		pcm.writeFloatLE(sample % rate === 0 ? 0.5 : 0, sample * 4);
	}
	const name = `impulses-${rate}.wav`;
	encode(
		name,
		["-f", "f32le", "-ar", String(rate), "-ac", "1", "-i", "pipe:0", "-c:a", "pcm_s16le"],
		pcm,
	);
	const decoded = run("ffmpeg", [
		"-v",
		"error",
		"-i",
		resolve(output, name),
		"-f",
		"s16le",
		"pipe:1",
	]);
	assert.equal(decoded.length, rate * 2 * 2);
	for (let sample = 0; sample < rate * 2; sample++) {
		assert.equal(decoded.readInt16LE(sample * 2), sample % rate === 0 ? 16384 : 0);
	}
}

const width = 160;
const height = 96;
const frameBytes = width * height * 3;
const frames = Buffer.alloc(frameBytes * 24);
for (let frame = 0; frame < 24; frame++) {
	for (let y = 0; y < height; y++) {
		for (let x = 0; x < width; x++) {
			const offset = frame * frameBytes + (y * width + x) * 3;
			const value = y < 32 ? ((frame >> Math.floor(x / 20)) & 1) * 255 : 64 + frame * 4;
			frames.fill(value, offset, offset + 3);
		}
	}
}
const rawInput = [
	"-f",
	"rawvideo",
	"-pixel_format",
	"rgb24",
	"-video_size",
	`${width}x${height}`,
	"-framerate",
	"12",
	"-i",
	"pipe:0",
];
const h264 = [
	"-c:v",
	"libx264",
	"-threads:v",
	"1",
	"-preset",
	"veryfast",
	"-crf",
	"18",
	"-pix_fmt",
	"yuv420p",
	"-flags:v",
	"+bitexact",
];
const variants = [
	{
		name: "cfr-av.mp4",
		options: [
			"-i",
			resolve(output, "impulses-48000.wav"),
			...h264,
			"-c:a",
			"aac",
			"-flags:a",
			"+bitexact",
		],
		ids: Array.from({ length: 24 }, (_, i) => i),
		start: 0,
	},
	{
		name: "vfr-silent.mp4",
		options: ["-vf", "select='not(eq(mod(n,3),1))'", "-fps_mode", "vfr", ...h264],
		ids: Array.from({ length: 24 }, (_, i) => i).filter((i) => i % 3 !== 1),
		start: 0,
	},
	{
		name: "nonzero-silent.mp4",
		options: [...h264, "-output_ts_offset", "5"],
		ids: Array.from({ length: 24 }, (_, i) => i),
		start: 5,
	},
	{
		name: "silent.webm",
		options: [
			"-c:v",
			"libvpx-vp9",
			"-threads:v",
			"1",
			"-crf",
			"20",
			"-b:v",
			"0",
			"-flags:v",
			"+bitexact",
		],
		ids: Array.from({ length: 24 }, (_, i) => i),
		start: 0,
	},
];
type ProbeFrame = { media_type: string; best_effort_timestamp_time: string };
type ProbeStream = { codec_type: string; codec_name: string };
type FixtureMetadata = { streams: ProbeStream[]; frameIds: number[]; timestamps: string[] };
const metadata: Record<string, FixtureMetadata> = {};
for (const variant of variants) {
	encode(variant.name, [...rawInput, ...variant.options], frames);
	const path = resolve(output, variant.name);
	const probe: { frames: ProbeFrame[]; streams: ProbeStream[] } = JSON.parse(
		run("ffprobe", [
			"-v",
			"error",
			"-show_streams",
			"-show_frames",
			"-of",
			"json",
			path,
		]).toString(),
	);
	assert.ok(Array.isArray(probe.frames) && Array.isArray(probe.streams));
	for (const frame of probe.frames) {
		assert.equal(typeof frame.media_type, "string");
		assert.ok(Number.isFinite(Number(frame.best_effort_timestamp_time)));
	}
	for (const stream of probe.streams) {
		assert.equal(typeof stream.codec_type, "string");
		assert.equal(typeof stream.codec_name, "string");
	}
	const videoFrames = probe.frames.filter(
		(frame: { media_type: string }) => frame.media_type === "video",
	);
	assert.equal(videoFrames.length, variant.ids.length);
	assert.ok(Math.abs(Number(videoFrames[0].best_effort_timestamp_time) - variant.start) < 0.001);
	if (variant.name.startsWith("vfr")) {
		const intervals = videoFrames
			.slice(1)
			.map((frame: { best_effort_timestamp_time: string }, i: number) =>
				Math.round(
					(Number(frame.best_effort_timestamp_time) -
						Number(videoFrames[i].best_effort_timestamp_time)) *
						1000,
				),
			);
		assert.ok(new Set(intervals).size > 1);
	}
	assert.equal(
		probe.streams.some((stream: { codec_type: string }) => stream.codec_type === "audio"),
		variant.name === "cfr-av.mp4",
	);
	const decoded = run("ffmpeg", [
		"-v",
		"error",
		"-i",
		path,
		"-map",
		"0:v:0",
		"-fps_mode",
		"passthrough",
		"-f",
		"rawvideo",
		"-pix_fmt",
		"rgb24",
		"pipe:1",
	]);
	assert.equal(decoded.length, frameBytes * variant.ids.length);
	for (const [index, id] of variant.ids.entries()) {
		let decodedId = 0;
		for (let bit = 0; bit < 8; bit++) {
			if (decoded[index * frameBytes + (16 * width + bit * 20 + 10) * 3]! > 128)
				decodedId |= 1 << bit;
		}
		assert.equal(decodedId, id, `${variant.name} frame ${index}`);
	}
	metadata[variant.name] = {
		streams: probe.streams,
		frameIds: variant.ids,
		timestamps: videoFrames.map(
			(frame: { best_effort_timestamp_time: string }) => frame.best_effort_timestamp_time,
		),
	};
}

const names = [
	...variants.map((variant) => variant.name),
	"impulses-44100.wav",
	"impulses-48000.wav",
];
const hashes = Object.fromEntries(
	names.map((name) => [
		name,
		createHash("sha256")
			.update(readFileSync(resolve(output, name)))
			.digest("hex"),
	]),
);
writeFileSync(
	resolve(output, "manifest.json"),
	JSON.stringify(
		{
			ffmpeg: execFileSync("ffmpeg", ["-version"]).toString().split("\n")[0],
			commands,
			hashes,
			metadata,
			audio: {
				channels: 1,
				durationSec: 2,
				impulseSamples: "0 and sampleRate",
				amplitude: 0.5,
				verifiedEverySample: true,
			},
		},
		null,
		2,
	) + "\n",
);
console.log(
	JSON.stringify(
		{ output, hashes, verifiedFrameIds: true, verifiedEveryAudioSample: true },
		null,
		2,
	),
);
